-- Phase 3b patch: dead stock episodes table and station repeated value warning configuration.
-- Additive PostgreSQL tenant upgrade only. Safe for existing tenant schemas.

CREATE TABLE IF NOT EXISTS "TankDeadStockEpisodes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FuelTankId" integer NOT NULL REFERENCES "FuelTanks" ("Id") ON DELETE RESTRICT,
    "TriggerReadingId" integer NOT NULL REFERENCES "TankLevelReadings" ("Id") ON DELETE RESTRICT,
    "StartedAtUtc" timestamp with time zone NOT NULL,
    "ResolvedAtUtc" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);

CREATE INDEX IF NOT EXISTS "IX_TankDeadStockEpisodes_Tank_Open"
    ON "TankDeadStockEpisodes" ("FuelTankId", "ResolvedAtUtc");

CREATE INDEX IF NOT EXISTS "IX_TankDeadStockEpisodes_TriggerReading"
    ON "TankDeadStockEpisodes" ("TriggerReadingId");

ALTER TABLE IF EXISTS "StationOperationalSettings"
    ADD COLUMN IF NOT EXISTS "RepeatedValueWarningCount" integer NOT NULL DEFAULT 6;
